// Lines that start with // are notes for people. The app skips them.
script "Spikes and stop rules" for navigation v1

// navigation-starter sees eight rays, the way to the finish and the path hint.
brain navigation-starter

// How close to the spikes is too close.
let margin = 0.5 m

// This block runs for every runner, 30 times per second.
each tick {
  // Move and turn exactly as the brain says.
  act(move: brain.move, turn: brain.turn)

  // Points for new ground, and ten more for crossing the line.
  reward +10 * agent.progressGain
  reward +10 when agent.finished
  // Spikes and movers end the run. That should cost something.
  reward -3 when agent.died
  // A small cost for every tick spent close to spikes.
  reward -0.01 when agent.spikeDistance < margin

  // End the run of a runner that found no new ground for 3 seconds.
  stop "slow" when agent.stuckTime > 3 s
}
